export function rb(w, h, d, r, mat, seg = 3) {
  const m = new THREE.Mesh(new RoundedBoxGeometry(w, h, d, seg, Math.min(r, Math.min(w, h, d) * 0.48)), mat);
  m.castShadow = true; m.receiveShadow = true;
  return m;
}

export function box(w, h, d, mat) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.castShadow = true; m.receiveShadow = true;
  return m;
}

export function cyl(r, len, mat, seg = 20, axis = 'z', r2 = null) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r2 ?? r, r, len, seg), mat);
  if (axis === 'z') m.rotation.x = Math.PI / 2;
  else if (axis === 'x') m.rotation.z = Math.PI / 2;
  m.castShadow = true; m.receiveShadow = true;
  return m;
}

export function torus(radius, tube, mat, radial = 10, tubular = 24) {
  const m = new THREE.Mesh(new THREE.TorusGeometry(radius, tube, radial, tubular), mat);
  m.castShadow = true; m.receiveShadow = true;
  return m;
}

export function pos(obj, x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0) {
  obj.position.set(x, y, z);
  obj.rotation.set(rx, ry, rz);
  return obj;
}

export function add(parent, obj, x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0) {
  pos(obj, x, y, z, rx, ry, rz);
  parent.add(obj);
  return obj;
}

export function screw(parent, x, y, z, r = 0.0035, mat = MAT.darkSteel, axis = 'x') {
  const m = cyl(r, 0.003, mat, 8, axis);
  add(parent, m, x, y, z);
  return m;
}

export function picatinny(parent, y, zStart, zEnd, mat = MAT.gunmetal, width = 0.022) {
  const len = Math.abs(zEnd - zStart);
  const zc = (zStart + zEnd) / 2;
  add(parent, box(width, 0.006, len, mat), 0, y, zc);
  const teeth = Math.floor(len / 0.0105);
  const geo = new THREE.BoxGeometry(width * 0.92, 0.0034, 0.0054);
  const inst = new THREE.InstancedMesh(geo, mat, teeth);
  const dummy = new THREE.Object3D();
  for (let i = 0; i < teeth; i++) {
    dummy.position.set(0, y + 0.0045, zStart - Math.sign(zStart - zEnd) * (0.008 + i * 0.0105));
    dummy.updateMatrix();
    inst.setMatrixAt(i, dummy.matrix);
  }
  inst.castShadow = true; inst.receiveShadow = true;
  parent.add(inst);
  return inst;
}

export function mlok(parent, x, y, z, side = 1, n = 3, spacing = 0.055, mat = MAT.rubber) {
  for (let i = 0; i < n; i++) {
    const m = rb(0.004, 0.008, 0.03, 0.001, mat, 1);
    add(parent, m, x + side * 0.001, y, z + (i - (n - 1) / 2) * spacing);
  }
}

export function knurl(parent, r, z, count, width, mat = MAT.darkSteel, axis = 'z') {
  for (let i = 0; i < count; i++) {
    const t = torus(r + 0.0007, 0.0011, mat, 4, 18);
    if (axis === 'z') t.rotation.x = 0; else t.rotation.y = Math.PI / 2;
    add(parent, t, 0, 0, z + (i - (count - 1) / 2) * width);
  }
}

export function textLabel(text, opts = {}) {
  const c = document.createElement('canvas');
  c.width = 512; c.height = 128;
  const g = c.getContext('2d');
  if (opts.bg) { g.fillStyle = opts.bg; g.fillRect(0, 0, 512, 128); }
  else g.clearRect(0, 0, 512, 128);
  g.fillStyle = opts.color || '#d6d2c2';
  g.font = `${opts.weight || 'bold'} ${opts.size || 52}px ${opts.font || 'monospace'}`;
  g.textAlign = 'center'; g.textBaseline = 'middle';
  g.fillText(text, 256, 64);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 8;
  const mat = new THREE.MeshBasicMaterial({ map: t, transparent: true, depthWrite: false, opacity: opts.opacity ?? 0.9 });
  const m = new THREE.Mesh(new THREE.PlaneGeometry(opts.w || 0.05, opts.h || 0.0125), mat);
  return m;
}

export function glowSprite(color = 0xffa030, size = 0.12, opacity = 0.8) {
  const c = document.createElement('canvas');
  c.width = c.height = 64;
  const g = c.getContext('2d');
  const grad = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  grad.addColorStop(0, 'rgba(255,255,255,0.95)');
  grad.addColorStop(0.25, `rgba(${(color >> 16) & 255},${(color >> 8) & 255},${color & 255},0.75)`);
  grad.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = grad; g.fillRect(0, 0, 64, 64);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  const m = new THREE.Sprite(new THREE.SpriteMaterial({ map: t, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, opacity }));
  m.scale.setScalar(size);
  return m;
}

export function curvedMagazine(width = 0.033, height = 0.16, depth = 0.062, mat = MAT.polymer) {
  const g = new THREE.Group();
  const segs = 3;
  let curX = 0, curY = 0, curAng = 0;
  for (let i = 0; i < segs; i++) {
    const segH = height / segs;
    curAng += 0.15;
    const seg = rb(width, segH * 1.15, depth, 0.006, mat, 2);
    seg.position.set(0, -segH * (i + 0.5) * 0.94, -Math.sin(curAng) * segH * i * 0.8);
    seg.rotation.x = -curAng * 0.8;
    g.add(seg);
    curY -= segH;
  }
  // ribs
  for (let i = 0; i < 4; i++) {
    const rib = rb(width + 0.002, 0.006, depth * 0.9, 0.002, MAT.blackOxide, 1);
    rib.position.set(0, -0.02 - i * 0.042, 0);
    g.add(rib);
  }
  const base = rb(width + 0.008, 0.012, depth + 0.01, 0.003, MAT.polymerSoft, 2);
  base.position.set(0, -height + 0.002, -0.008);
  g.add(base);
  return g;
}

export function bulletTip(parent, x, y, z, scale = 1, axis = 'z') {
  const b = cyl(0.004 * scale, 0.018 * scale, MAT.brass, 10, axis, 0.0012 * scale);
  add(parent, b, x, y, z);
  return b;
}

export function triggerGuard(parent, mat = MAT.gunmetal) {
  // flattened torus segment approximated with a thin rounded box loop
  const g = new THREE.Group();
  add(g, rb(0.045, 0.006, 0.008, 0.002, mat, 1), 0, -0.042, 0.0);
  add(g, rb(0.006, 0.036, 0.008, 0.002, mat, 1), -0.0195, -0.024, 0.0);
  add(g, rb(0.006, 0.030, 0.008, 0.002, mat, 1), 0.0195, -0.027, 0.0);
  parent.add(g);
  return g;
}

export function safetyLever(parent, x = 0.031, y = -0.005, z = 0.02, mat = MAT.gunmetal) {
  add(parent, rb(0.004, 0.018, 0.03, 0.002, mat, 1), x, y, z);
  add(parent, cyl(0.006, 0.004, mat, 12, 'x'), x + 0.003, y, z);
}

export function qdSlingPoint(parent, x, y, z, mat = MAT.darkSteel) {
  const t = torus(0.008, 0.0022, mat, 6, 14);
  t.rotation.y = Math.PI / 2;
  add(parent, t, x, y, z);
}

export function createMount(parent, y, z, height = 0.024, width = 0.026, mat = MAT.gunmetal) {
  add(parent, rb(width, height, 0.03, 0.003, mat, 2), 0, y + height / 2, z);
  for (const s of [-1, 1]) {
    add(parent, cyl(0.003, 0.004, MAT.darkSteel, 6, 'x'), s * (width / 2 + 0.001), y + height * 0.6, z);
  }
}

export function lensDisc(radius, mat = MAT.lens) {
  const m = new THREE.Mesh(new THREE.CircleGeometry(radius, 28), mat);
  m.rotation.y = Math.PI;
  return m;
}

export function tacticalGloveHand(side = 'right', scale = 1, mat = MAT.glove) {
  const g = new THREE.Group();
  const palm = rb(0.052, 0.072, 0.07, 0.015, mat, 3);
  g.add(palm);
  // knuckle pads
  for (let i = 0; i < 4; i++) {
    const k = rb(0.011, 0.012, 0.018, 0.004, MAT.gloveDark, 2);
    k.position.set(-0.019 + i * 0.0125, 0.035, -0.031);
    g.add(k);
  }
  // fingers curling around the front
  for (let i = 0; i < 4; i++) {
    const x = -0.019 + i * 0.0125;
    const f1 = rb(0.0105, 0.034, 0.012, 0.0045, mat, 2);
    f1.position.set(x, 0.006, -0.040);
    f1.rotation.x = 0.2;
    g.add(f1);
    const f2 = rb(0.0098, 0.009, 0.025, 0.004, mat, 2);
    f2.position.set(x, -0.018, -0.027);
    f2.rotation.x = -0.85;
    g.add(f2);
  }
  // thumb
  const th = rb(0.013, 0.048, 0.016, 0.006, mat, 2);
  th.position.set(side === 'right' ? 0.031 : -0.031, 0.008, -0.012);
  th.rotation.z = side === 'right' ? -0.55 : 0.55;
  th.rotation.x = -0.15;
  g.add(th);
  // wrist cuff
  const cuff = cyl(0.025, 0.03, MAT.gloveDark, 12, 'z');
  cuff.position.set(0, -0.02, 0.045);
  g.add(cuff);
  g.scale.setScalar(scale);
  return g;
}

export function forearm(side, from, to, radius = 0.028) {
  const g = new THREE.Group();
  const a = new THREE.Vector3(...from);
  const b = new THREE.Vector3(...to);
  const dir = b.clone().sub(a);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(radius * 0.78, radius, len, 12, 1);
  const m = new THREE.Mesh(geo, MAT.camo);
  m.castShadow = true;
  m.position.copy(a.clone().add(b).multiplyScalar(0.5));
  m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  g.add(m);
  // cuff at wrist
  const cuff = cyl(radius * 0.86, 0.035, MAT.gloveDark, 12, 'z');
  const cuffDir = dir.clone().normalize();
  cuff.position.copy(a).add(cuffDir.clone().multiplyScalar(0.018));
  cuff.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), cuffDir);
  g.add(cuff);
  // sleeve wrinkle bands
  for (let i = 0; i < 3; i++) {
    const band = torus(radius * 0.92, 0.0015, MAT.camoDark, 4, 12);
    band.quaternion.copy(m.quaternion);
    band.position.copy(a).lerp(b, 0.3 + i * 0.16);
    band.rotateX(Math.PI / 2);
    g.add(band);
  }
  return g;
}

import * as THREE from 'three';
import {
  MAT, rb, box, cyl, torus, add, pos, screw, picatinny, mlok, knurl,
  textLabel, glowSprite, curvedMagazine, triggerGuard, safetyLever, qdSlingPoint,
  createMount, lensDisc,
} from './parts.js';

const V = (x, y, z) => new THREE.Vector3(x, y, z);

function newWeapon() {
  const group = new THREE.Group();
  group.name = 'weapon';
  return group;
}

function ironSights(g, rearZ = 0.06, frontZ = -0.41, y = 0.086, rearY = null) {
  const irons = new THREE.Group();
  // flip-up rear aperture
  const rear = new THREE.Group();
  add(rear, rb(0.026, 0.008, 0.022, 0.002, MAT.gunmetal, 2), 0, 0, 0);
  const ring = torus(0.0085, 0.0018, MAT.gunmetal, 6, 16);
  ring.rotation.y = Math.PI / 2;
  add(rear, ring, 0, 0.016, 0);
  add(rear, box(0.003, 0.025, 0.003, MAT.gunmetal), -0.012, 0.012, 0);
  add(rear, box(0.003, 0.025, 0.003, MAT.gunmetal), 0.012, 0.012, 0);
  add(irons, rear, 0, rearY ?? y + 0.018, rearZ);
  // front post
  const front = new THREE.Group();
  add(front, rb(0.024, 0.008, 0.024, 0.002, MAT.gunmetal, 2), 0, 0, 0);
  add(front, box(0.003, 0.028, 0.004, MAT.gunmetal), 0, 0.016, 0);
  add(front, box(0.014, 0.003, 0.004, MAT.gunmetal), 0, 0.029, 0);
  add(irons, front, 0, y + 0.017, frontZ);
  g.add(irons);
  return irons;
}

function buildAr15Base(g, opts = {}) {
  const fde = opts.fde;
  const receiverMat = fde ? MAT.fdeDark : MAT.gunmetal;
  const handguardMat = fde ? MAT.fde : MAT.gunmetal;

  // ---- lower receiver ----
  add(g, rb(0.043, 0.072, 0.20, 0.006, receiverMat, 4), 0, -0.004, -0.005);
  // magwell flare
  add(g, rb(0.050, 0.075, 0.088, 0.004, receiverMat, 3), 0, -0.068, -0.042);
  // trigger pocket / guard
  const guard = triggerGuard(g, receiverMat);
  guard.position.set(0, -0.018, 0.016);
  // pistol grip
  const grip = rb(0.038, 0.108, 0.056, 0.013, MAT.polymer, 3);
  add(g, grip, 0, -0.092, 0.079, -0.30);
  add(g, rb(0.041, 0.016, 0.058, 0.005, MAT.polymerSoft, 2), 0, -0.145, 0.096, -0.30);
  // grip texture
  for (let i = 0; i < 5; i++) add(g, rb(0.039, 0.004, 0.052, 0.001, MAT.blackOxide, 1), 0, -0.065 - i * 0.016, 0.071 + i * 0.005, -0.30);

  // ---- upper receiver ----
  add(g, rb(0.045, 0.060, 0.265, 0.006, receiverMat, 4), 0, 0.048, -0.058);
  // brass deflector
  const defl = cyl(0.013, 0.02, receiverMat, 10, 'x');
  add(g, defl, 0.025, 0.040, 0.018);
  // ejection port
  add(g, rb(0.004, 0.026, 0.062, 0.002, MAT.blackOxide, 2), 0.0225, 0.050, -0.048);
  add(g, box(0.002, 0.004, 0.058, MAT.darkSteel), 0.0245, 0.065, -0.048);
  // forward assist
  add(g, cyl(0.010, 0.022, MAT.darkSteel, 14, 'x'), 0.030, 0.042, -0.010);
  add(g, cyl(0.006, 0.006, MAT.gunmetal, 12, 'x'), 0.042, 0.042, -0.010);
  // charging handle
  add(g, box(0.035, 0.010, 0.026, MAT.gunmetal), 0, 0.076, 0.068);
  add(g, box(0.055, 0.005, 0.008, MAT.gunmetal), 0, 0.076, 0.080);
  // dust cover
  add(g, rb(0.003, 0.030, 0.066, 0.001, MAT.darkSteel, 1), 0.0242, 0.049, -0.049, 0, 0, 0.1);
  // bolt catch / mag release / safety
  add(g, rb(0.007, 0.016, 0.030, 0.002, MAT.darkSteel, 1), 0.032, -0.003, -0.010);
  add(g, cyl(0.007, 0.008, MAT.darkSteel, 12, 'x'), 0.032, -0.030, 0.030);
  safetyLever(g, 0.030, -0.003, 0.045);

  // ---- top rail ----
  picatinny(g, 0.083, 0.072, -0.205, MAT.gunmetal, 0.022);

  // ---- handguard ----
  const hgStart = -0.195, hgEnd = -0.435;
  const hg = cyl(0.036, hgEnd - hgStart, handguardMat, 10);
  add(g, hg, 0, 0.048, (hgStart + hgEnd) / 2);
  // barrel nut / delta ring
  add(g, cyl(0.040, 0.032, MAT.darkSteel, 16), 0, 0.048, hgStart + 0.006);
  add(g, cyl(0.038, 0.012, receiverMat, 14), 0, 0.048, hgStart - 0.010);
  // top rail continuation
  picatinny(g, 0.083, hgStart + 0.005, hgEnd + 0.008, handguardMat, 0.022);
  // mlok slots on sides and bottom
  for (const side of [-1, 1]) {
    for (let i = 0; i < 3; i++) {
      const z = -0.25 - i * 0.058;
      add(g, rb(0.004, 0.014, 0.038, 0.002, MAT.blackOxide, 1), side * 0.0345, 0.048, z);
      add(g, rb(0.002, 0.010, 0.030, 0.001, MAT.rubber, 1), side * 0.0370, 0.048, z);
    }
  }
  for (let i = 0; i < 3; i++) {
    const z = -0.245 - i * 0.058;
    add(g, rb(0.024, 0.003, 0.034, 0.001, MAT.blackOxide, 1), 0, 0.015, z);
  }
  // handguard end cap
  add(g, cyl(0.034, 0.010, MAT.darkSteel, 12), 0, 0.048, hgEnd + 0.002);

  // ---- barrel ----
  const barrelLen = opts.barrel || 0.17;
  add(g, cyl(0.0115, barrelLen, MAT.darkSteel, 16), 0, 0.048, hgEnd - barrelLen / 2 + 0.004);
  add(g, cyl(0.014, 0.030, MAT.darkSteel, 16), 0, 0.048, hgEnd - 0.020);
  // low profile gas block + gas tube
  add(g, box(0.030, 0.038, 0.030, MAT.darkSteel), 0, 0.040, hgEnd + 0.034);
  add(g, cyl(0.0045, 0.16, MAT.darkSteel, 8), 0, 0.064, hgEnd + 0.10);

  // ---- buffer tube ----
  add(g, cyl(0.0165, 0.19, MAT.gunmetal, 14), 0, 0.046, 0.170);
  add(g, torus(0.019, 0.003, MAT.darkSteel, 6, 18), 0, 0.046, 0.075);
  // castle nut
  knurl(g, 0.019, 0.083, 3, 0.005, MAT.darkSteel);
  // rear sling point
  add(g, rb(0.010, 0.020, 0.014, 0.002, MAT.darkSteel, 1), 0.026, 0.030, 0.074);
  screw(g, 0.026, 0.030, 0.074, 0.0038);

  // ---- magazine ----
  const mag = curvedMagazine(0.034, 0.155, 0.064, MAT.polymer);
  add(g, mag, 0, -0.083, -0.045);
  // floor plate
  add(g, rb(0.042, 0.012, 0.075, 0.003, MAT.polymerSoft, 2), 0, -0.232, -0.032, 0.08);

  // ---- trigger ----
  const trig = rb(0.005, 0.028, 0.008, 0.002, MAT.darkSteel, 2);
  add(g, trig, 0, -0.045, 0.030, 0.18);
  add(g, rb(0.006, 0.006, 0.010, 0.002, MAT.gunmetal, 1), 0, -0.030, 0.030);

  // ---- stamps ----
  const lab = textLabel('WW-15', { size: 70, w: 0.05, h: 0.0125, color: '#b9b5a8', opacity: 0.7 });
  add(g, lab, -0.0224, 0.008, -0.032, 0, -Math.PI / 2, 0);
  const cal = textLabel('5.56 NATO', { size: 46, w: 0.036, h: 0.009, color: '#9a978d', opacity: 0.65 });
  add(g, cal, -0.0224, 0.030, -0.075, 0, -Math.PI / 2, 0);

  return { guard, grip, mag, trigger: trig, hgEnd };
}

function stockAR(g, type = 'adjustable') {
  const stock = new THREE.Group();
  // main body skeleton
  add(stock, rb(0.044, 0.070, 0.120, 0.014, MAT.polymer, 4), 0, 0.000, 0.145);
  add(stock, rb(0.048, 0.100, 0.028, 0.010, MAT.polymerSoft, 3), 0, -0.005, 0.206);
  // cheek rest
  add(stock, rb(0.040, 0.026, 0.090, 0.008, MAT.polymerSoft, 2), 0, 0.038, 0.145);
  // adjustment lever
  add(stock, box(0.014, 0.012, 0.040, MAT.darkSteel), 0.024, -0.020, 0.150);
  add(stock, cyl(0.006, 0.014, MAT.darkSteel, 10, 'x'), 0.030, -0.024, 0.160);
  // QD sling slot
  add(stock, rb(0.016, 0.008, 0.024, 0.003, MAT.rubber, 1), -0.018, 0.020, 0.168);
  // buttpad
  add(stock, rb(0.047, 0.104, 0.012, 0.005, MAT.rubber, 3), 0, -0.004, 0.215);
  // ribs
  for (let i = 0; i < 3; i++) add(stock, box(0.030, 0.002, 0.06, MAT.blackOxide), 0, 0.042 - i * 0.02, 0.120);
  g.add(stock);
  return stock;
}

/* ============================================================
   WINDHAM WEAPONRY WW-15
   holo sight · modified trigger · muzzle brake · foregrip · buttstock
   ============================================================ */
function buildWW15() {
  const g = newWeapon();
  const meta = { parts: {} };
  buildAr15Base(g, { barrel: 0.18 });

  // stock
  const stock = stockAR(g);
  meta.parts.stock = stock;

  // ---- muzzle brake ----
  const brake = new THREE.Group();
  add(brake, cyl(0.016, 0.058, MAT.darkSteel, 18), 0, 0, 0);
  add(brake, cyl(0.018, 0.008, MAT.gunmetal, 18), 0, 0, -0.028);
  for (let i = 0; i < 3; i++) {
