    add(legs, rb(0.080, 0.120, 0.045, 0.014, MAT.camo, 3), s * 0.170, 0.720, -0.010, 0, 0, s * 0.06);
    add(legs, box(0.080, 0.012, 0.048, MAT.camoDark), s * 0.172, 0.770, -0.014, 0, 0, s * 0.06);
